<?php
require_once '/opt/hr/HrBatchSupport.php';require_once '/opt/hr/HrUi.php';global $current_user;
if(!BeanFactory::newBean('HR_People')->ACLAccess('list')||!BeanFactory::newBean('HR_People')->ACLAccess('edit')){http_response_code(403);die('Нет доступа к пакетной генерации.');}
$_SESSION['hr_csrf']??=bin2hex(random_bytes(24));$labels=hrDocumentLabels();unset($labels['applicant_dative']);$draft=array_replace(hrDocumentDefaults(),$_SESSION['hr_batch_draft']??[]);$selected=$_SESSION['hr_batch_people']??[];$error='';$batch=null;
if($_SERVER['REQUEST_METHOD']==='POST')try{
 if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['hr_csrf'],$_POST['csrf']))throw new RuntimeException('Сессия формы устарела. Обновите страницу.');
 foreach($draft as $key=>$value)if(is_string($_POST[$key]??null))$draft[$key]=$_POST[$key];$selected=is_array($_POST['people']??null)?array_values(array_filter($_POST['people'],'is_string')):[];
 $_SESSION['hr_batch_draft']=$draft;$_SESSION['hr_batch_people']=$selected;
 $request=$_POST['request']??'';if(!is_string($request)||!preg_match('/^[a-f0-9]{32}$/D',$request)||!isset($_SESSION['hr_batch_requests'][$request]))throw new RuntimeException('Форма устарела. Повторите отправку.');
 if($_SESSION['hr_batch_requests'][$request]!==false){header('Location: '.hrUiUrl('HrBatch',['batch'=>$_SESSION['hr_batch_requests'][$request]]),true,303);exit;}
 $leave=[];foreach($labels as $key=>$label)$leave[$key]=trim($draft['leave_'.$key]??'');
 if(is_file(hrDir().'/batch-'.$request.'.json')){$existing=hrBatchRead($request);$id=$existing['id'];}else{$id=hrBatchCreate($selected,$draft['template'],$leave,$request);}$_SESSION['hr_batch_requests'][$request]=$id;header('Location: '.hrUiUrl('HrBatch',['batch'=>$id]),true,303);exit;
}catch(Throwable $e){$error=$e->getMessage();}
if(isset($_GET['batch']))try{
 $batch=hrBatchRead($_GET['batch']);
 if(isset($_GET['download'])){$path=hrBatchArchive($batch);header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="documents-'.$batch['id'].'.zip"');header('Cache-Control: private, no-store');header('Content-Length: '.filesize($path));try{readfile($path);}finally{unlink($path);}exit;}
}catch(Throwable $e){http_response_code(403);$error=$e->getMessage();}
$request=bin2hex(random_bytes(16));$_SESSION['hr_batch_requests'][$request]=false;$_SESSION['hr_batch_requests']=array_slice($_SESSION['hr_batch_requests']??[],-30,null,true);
$people=BeanFactory::newBean('HR_People')->get_list('name','',0,200,200)['list'];
?><!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Пакетная генерация документов</title><?php hrUiStyle();?><body class="hr-page"><main class="hr-shell"><?php hrUiNav('documents');?><h1>Документы для нескольких сотрудников</h1><p class="hr-muted">Один шаблон и общие параметры — отдельный документ для каждого человека. ФИО, звание, должность и сведения из карточки подставляются индивидуально.</p><div class="hr-actions"><a href="<?=hrUiEscape(hrUiUrl('HrLibrary'))?>">К документам</a><a href="<?=hrUiEscape(hrUiGuide('batch'))?>">Инструкция</a></div>
<?php if($error):?><div class="error" role="alert"><?=hrUiEscape($error)?> Введённые параметры сохранены.</div><?php endif?>
<?php if($batch):?><section class="hr-panel"><h2>Результаты пакета</h2><p>Создал: <strong><?=hrUiEscape($batch['author_name'])?></strong>. Шаблон: <?=hrUiEscape($batch['title'])?>.</p><div class="hr-actions"><a class="hr-button" href="<?=hrUiEscape(hrUiUrl('HrBatch',['batch'=>$batch['id'],'download'=>1]))?>">Скачать ZIP с DOCX и PDF</a></div><div class="hr-table-wrap"><table class="hr-table"><thead><tr><th>Сотрудник</th><th>Результат</th></tr></thead><tbody><?php foreach($batch['results'] as $row):?><tr><td><?=hrUiEscape($row['person_name'])?></td><td><?php if(isset($row['document'])):?><a href="<?=hrUiEscape(hrUiUrl('HrDocuments',['person'=>$row['person_id'],'document'=>$row['document']]))?>">Открыть документ</a><?php else:?><span class="field-error"><?=hrUiEscape($row['error'])?></span><?php endif?></td></tr><?php endforeach?></tbody></table></div><p class="hr-hint">Готовые документы также доступны в истории каждого сотрудника. Обновление страницы не создаёт копии.</p></section><?php endif?>
<form method="post" id="batch-form" class="hr-panel" action="<?=hrUiEscape(hrUiUrl('HrBatch'))?>"><input type="hidden" name="csrf" value="<?=hrUiEscape($_SESSION['hr_csrf'])?>"><input type="hidden" name="request" value="<?=$request?>"><h2>1. Выберите сотрудников</h2><label>Поиск в списке<input id="batch-search" type="search" placeholder="Введите ФИО"></label><div class="hr-actions"><button class="hr-button secondary" type="button" id="batch-select">Выбрать видимых</button><button class="hr-button secondary" type="button" id="batch-clear">Снять выбор</button><span id="batch-count" aria-live="polite"></span></div><div style="max-height:320px;overflow:auto" class="hr-table-wrap"><table class="hr-table"><thead><tr><th>Выбрать</th><th>ФИО</th><th>Должность</th></tr></thead><tbody><?php foreach($people as $person):if(!$person->ACLAccess('view')||!$person->ACLAccess('edit'))continue;?><tr data-person="<?=hrUiEscape(mb_strtolower($person->name))?>"><td><input type="checkbox" name="people[]" value="<?=hrUiEscape($person->id)?>" aria-label="<?=hrUiEscape('Выбрать: '.$person->name)?>" <?=in_array($person->id,$selected,true)?'checked':''?>></td><td><?=hrUiEscape($person->name)?></td><td><?=hrUiEscape($person->position)?></td></tr><?php endforeach?></tbody></table></div><p class="hr-hint">До 20 сотрудников за один запуск. В списке показаны первые 200 доступных записей.</p><h2>2. Выберите шаблон</h2><label>Шаблон<select name="template" id="batch-template"><?php foreach(hrTemplates() as $key=>$title):?><option value="<?=hrUiEscape($key)?>" data-kind="<?=hrUiEscape(hrTemplateKind($key))?>" <?=$draft['template']===$key?'selected':''?>><?=hrUiEscape($title)?></option><?php endforeach?></select></label>
<div id="batch-leave"><h2>3. Общие параметры рапорта</h2><p class="hr-hint">ФИО и звание берутся отдельно из каждой карточки. Общий текст не должен содержать имя конкретного заявителя. Пустой адресат и согласующий заполняются по руководителю каждого сотрудника.</p><div class="hr-form-grid"><?php foreach($labels as $key=>$label):$type=in_array($key,['start','end','following_start','following_end','return_date','report_date'])?'date':($key==='return_time'?'time':'text');?><label><?=hrUiEscape($label)?><input type="<?=$type?>" name="leave_<?=hrUiEscape($key)?>" value="<?=hrUiEscape($draft['leave_'.$key]??'')?>" maxlength="2000"></label><?php endforeach?></div></div><div class="hr-actions"><button id="batch-submit"><?=$batch?'Сформировать новый пакет':'Сформировать документы'?></button><span id="batch-status" class="hr-hint" role="status">Параметры сохраняются. Создание нескольких документов может занять около минуты.</span></div></form>
<script>
(()=>{const form=document.getElementById('batch-form'),rows=[...form.querySelectorAll('[data-person]')],boxes=[...form.querySelectorAll('[name="people[]"]')],select=document.getElementById('batch-template');function count(){document.getElementById('batch-count').textContent='Выбрано: '+boxes.filter(x=>x.checked).length+' из 20';}document.getElementById('batch-search').addEventListener('input',e=>rows.forEach(row=>row.hidden=!row.dataset.person.includes(e.target.value.toLocaleLowerCase('ru'))));document.getElementById('batch-select').addEventListener('click',()=>{for(const row of rows){if(row.hidden)continue;const box=row.querySelector('input');if(!box.checked&&boxes.filter(x=>x.checked).length<20)box.checked=true;}count();});document.getElementById('batch-clear').addEventListener('click',()=>{boxes.forEach(box=>box.checked=false);count();});boxes.forEach(box=>box.addEventListener('change',count));function toggle(){document.getElementById('batch-leave').hidden=select.selectedOptions[0].dataset.kind!=='leave';}select.addEventListener('change',toggle);toggle();count();form.addEventListener('submit',e=>{const n=boxes.filter(x=>x.checked).length;if(n<1||n>20){e.preventDefault();document.getElementById('batch-status').textContent='Выберите от 1 до 20 сотрудников.';return;}document.getElementById('batch-submit').disabled=true;document.getElementById('batch-status').textContent='Формируются документы для '+n+' сотрудников. Дождитесь результата…';});})();
</script></main></body></html>
